# scripts/tur_data_wing2.py
# Ottoman Focus Tree - Wing 2: Imperial Economy & Autarky (53 focuses)

WING_2 = {'TUR_economic_sovereignty_drive': {'pt_t': 'Campanha pela Soberania Econômica', 'en_t': 'Economic Sovereignty Drive', 'pt_d': 'A Sublime Porta inicia um esforço coordenado para livrar as finanças imperiais da tutela sufocante de banqueiros e credores estrangeiros.', 'en_d': 'The Sublime Porte initiates a concerted campaign to liberate imperial finances from the stifling tutelage of European bondholders.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_audit_opda_administration': {'pt_t': 'Auditoria da Administração da Dívida (OPDA)', 'en_t': 'Audit OPDA Administration', 'pt_d': 'Inspetores imperiais entram nos escritórios da Administração da Dívida Pública Otomana, examinando receitas e contestando deduções abusivas.', 'en_d': 'Imperial inspectors enter the headquarters of the Ottoman Public Debt Administration (OPDA), auditing revenue ledgers and contesting exorbitant deductions.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_renegotiate_creditor_coupons': {'pt_t': 'Renegociação dos Títulos com Credores', 'en_t': 'Renegotiate Creditor Coupons', 'pt_d': 'Diplomatas em Paris e Londres renegociam prazos e taxas de juros dos títulos consolidados de 1903, aliviando o fluxo de caixa do Tesouro.', 'en_d': 'Ottoman envoys in Paris and London renegotiate bond redemption dates and coupon interest, easing immediate pressure on imperial cash reserves.', 'icon': 'gfx/interface/goals/GFX_TUR_german_donation-96235.dds'}, 'TUR_unilateral_abrogation_of_capitulations': {'pt_t': 'Revogação Unilateral das Capitulações', 'en_t': 'Unilateral Abrogation of Capitulations', 'pt_d': 'Um decreto histórico extingue todos os privilégios extraterritoriais, isenções fiscais e imunidades judiciais desfrutadas por súditos europeus no Império.', 'en_d': 'A historic imperial decree extinguishes all extraterritorial privileges, tax immunities, and consular judicial shelters enjoyed by European nationals.', 'icon': 'gfx/interface/goals/GFX_TUR_abolished_the_capitulations-46466.dds'}, 'TUR_protective_tariff_code': {'pt_t': 'Novo Código de Tarifas Alfandegárias', 'en_t': 'Protective Customs Tariff Code', 'pt_d': 'Pela primeira vez em um século, a Sublime Porta impõe tarifas alfandegárias de até 30% sobre produtos importados para proteger oficinas artesanais e fábricas nacionais.', 'en_d': 'For the first time in a century, the Porte enacts protective customs duties up to 30% on foreign manufactured goods, shielding domestic factories.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_national_bank_osmanli_itibar': {'pt_t': 'Fundação do Banco Osmanlı İtibar-ı Millî', 'en_t': 'Founding of Osmanlı İtibar-ı Millî Bankası', 'pt_d': 'A criação do Banco Nacional de Crédito Imperial substitui o domínio do consórcio anglo-francês, fornecendo crédito estatal a empreendedores do império.', 'en_d': 'The founding of the Imperial National Credit Bank breaks the monopoly of Anglo-French financiers, issuing state-backed capital to Ottoman enterprises.', 'icon': 'gfx/interface/goals/GFX_TUR_german_donation-96235.dds'}, 'TUR_confiscate_foreign_monopolies': {'pt_t': 'Reestatização dos Monopólios Estrangeiros', 'en_t': 'Confiscate Foreign Monopolies', 'pt_d': 'Docas portuárias, empresas de bondes elétricos e usinas de gás geridas por concessões estrangeiras são transferidas à administração pública imperial.', 'en_d': 'Harbor quays, tramlines, and gaslight utilities operated by foreign concessions are reclaimed under direct Ottoman municipal management.', 'icon': 'gfx/interface/goals/GFX_TUR_abolished_the_capitulations-46466.dds'}, 'TUR_monetary_autonomy_and_gold_lira': {'pt_t': 'Emissão Autônoma da Lira de Ouro', 'en_t': 'Monetary Autonomy and Gold Lira', 'pt_d': 'A emissão de moeda passa para o controle exclusivo do Tesouro Imperial, lastreada em reservas de ouro e prata guardadas na capital.', 'en_d': 'The printing of paper notes passes to direct treasury authority, backed by solid reserves of bullion deposited within the imperial vaults.', 'icon': 'gfx/interface/goals/GFX_TUR_german_donation-96235.dds'}, 'TUR_tobacco_regie_liquidation': {'pt_t': 'Liquidação da Régie Francesa do Tabaco', 'en_t': 'Liquidation of the Tobacco Régie', 'pt_d': 'O odiado monopólio da Régie Co-Intéressée é extinto, permitindo que os camponeses e fumicultores da Anatólia e Trácia vendam sua safra livremente.', 'en_d': 'The hated concession of the French-dominated Tobacco Régie is liquidated, granting Anatolian leaf growers freedom to sell directly to imperial markets.', 'icon': 'gfx/interface/goals/GFX_TUR_abolished_the_capitulations-46466.dds'}, 'TUR_salt_monopoly_nationalization': {'pt_t': 'Nacionalização do Monopólio do Sal', 'en_t': 'Nationalization of the Salt Monopoly', 'pt_d': 'As salinas do Lago Tuz e da costa do Mar Egeu passam para o controle estatal, canalizando lucros vitais diretamente para os cofres do Exército.', 'en_d': 'The vast salt pans of Lake Tuz and the Aegean shores are placed under state trusteeship, directing vital revenues straight to imperial defense funds.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_complete_fiscal_liberation': {'pt_t': 'Emancipação Fiscal Plena', 'en_t': 'Complete Fiscal Liberation', 'pt_d': 'Com a dívida reestruturada e as capitulações revogadas, a Sublime Porta alcança plena independência orçamentária perante o mundo.', 'en_d': 'With public debt consolidated and capitulatory shackles broken, the Sublime Porte achieves genuine fiscal independence before the world.', 'icon': 'gfx/interface/goals/GFX_TUR_abolished_the_capitulations-46466.dds'}, 'TUR_taurus_and_amanus_tunnels': {'pt_t': 'Túneis dos Montes Taurus e Amanus', 'en_t': 'Taurus and Amanus Mountain Tunnels', 'pt_d': 'Engenheiros alemães e turcos abrem passagens ferroviárias cruciais pelas cordilheiras de Taurus e Amanus, eliminando o gargalo de baldeação a cavalo.', 'en_d': 'German and Ottoman engineers blast essential rail tunnels through the rugged Taurus and Amanus peaks, closing the last physical gaps in the southern trunk.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_konya_aleppo_trunk_line': {'pt_t': 'Linha Tronco Konya–Aleppo', 'en_t': 'Konya–Aleppo Trunk Line', 'pt_d': 'A ferrovia conecta o planalto central anatólio à metrópole mercantil síria, permitindo a viagem contínua de trens militares e composições de carga.', 'en_d': 'Direct broad-gauge rails link central Anatolia with the Syrian trade metropolis of Aleppo, permitting continuous transit for military supply trains.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_aleppo_to_mosul_extension': {'pt_t': 'Extensão de Aleppo a Mosul', 'en_t': 'Aleppo–Mosul Rail Extension', 'pt_d': 'Os trilhos avançam pela estepe da Alta Mesopotâmia em direção a Nusaybin e Mosul, acelerando o reforço das fronteiras orientais.', 'en_d': 'Railway gangs push steel tracks across Upper Mesopotamia toward Nusaybin and Mosul, dramatically accelerating reinforcement of the eastern frontier.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_mosul_baghdad_railhead': {'pt_t': 'Ponta de Trilhos Mosul–Bagdá', 'en_t': 'Mosul–Baghdad Railhead', 'pt_d': 'A conexão ferroviária com a antiga capital abássida estabelece uma rota logística imbatível que assegura a integridade territorial do vale mesopotâmico.', 'en_d': 'The rail line reaches Baghdad, cementing an unassailable supply artery that secures the Tigris basin against foreign amphibious inroads.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdad_industrialization-45108.dds'}, 'TUR_basra_terminus_settlement': {'pt_t': 'Terminal Ferroviário de Basra', 'en_t': 'Basra Rail Terminus Port', 'pt_d': 'Docas modernas e armazéns conectam a ferrovia às águas do Golfo Pérsico, estabelecendo uma saída comercial protegida para o comércio oriental.', 'en_d': 'Modernized quays and marshalling yards link the railroad to the Persian Gulf, providing an outlet for Mesopotamian dates and grain shipments.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdad_industrialization-45108.dds'}, 'TUR_hejaz_railway_expansion': {'pt_t': 'Expansão da Ferrovia de Hejaz', 'en_t': 'Hejaz Railway Strategic Expansion', 'pt_d': 'A lendária linha construída com donativos muçulmanos recebe novas oficinas de reparo de locomotivas e ramais de abastecimento de água no deserto.', 'en_d': 'The famed pilgrim railway receives expanded desert sidings, water-condensing locomotives, and reinforced stations from Damascus to Medina.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_syrian_feeder_lines': {'pt_t': 'Ramais Ferroviários Sírios', 'en_t': 'Syrian Railway Feeder Lines', 'pt_d': 'Ramais ligam Rayak, Homs, Trípoli e Beirute, criando uma teia logística que abastece portos e tropas com máxima flexibilidade.', 'en_d': 'Feeder branches connect Rayak, Homs, Tripoli, and Beirut, weaving an integrated transport network between Mediterranean docks and interior garrisons.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_medina_to_mecca_link': {'pt_t': 'Ligação Férrea Medina–Meca', 'en_t': 'Medina–Mecca Railway Link', 'pt_d': 'O projeto histórico de estender os trilhos até a Cidade Sagrada de Meca aproxima fiéis de todo o mundo e assegura proteção imediata à Caaba.', 'en_d': 'Surveyors lay trackbeds to extend the sacred line south to Mecca, fulfilling a historic ambition to link both holy sanctuaries by steam power.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_jerusalem_jaffa_railway_upgrade': {'pt_t': 'Modernização da Linha Jaffa–Jerusalém', 'en_t': 'Jaffa–Jerusalem Railway Upgrade', 'pt_d': 'A conversão da bitola e a compra de locomotivas de montanha aumentam a capacidade de transporte militar e peregrino nas colinas da Judeia.', 'en_d': 'Gauge conversion and powerful mountain locomotives double transit capacity across the Judean hills, securing the approaches to the holy shrines.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_anatolian_railway_loop': {'pt_t': 'Anel Ferroviário da Anatólia Central', 'en_t': 'Central Anatolian Railway Loop', 'pt_d': 'A interconexão de linhas entre Ankara, Eskişehir, Afyon e Konya cria um loop contínuo que impede congestionamentos na movimentação de tropas.', 'en_d': 'Linking Ankara, Eskişehir, Afyon, and Konya into a continuous loop prevents logistical bottlenecks during peak army mobilization.', 'icon': 'gfx/interface/goals/GFX_TUR_ankara_industrialization-45108.dds'}, 'TUR_railway_telegraph_integration': {'pt_t': 'Telégrafo Ferroviário Integrado', 'en_t': 'Railway Telegraphic Integration', 'pt_d': 'Linhas telegráficas dedicadas acompanham cada quilômetro de trilhos, permitindo à Sublime Porta acompanhar horários de trens e despachos em tempo real.', 'en_d': 'Dedicated copper telegraph wires parallel every railway embankment, granting the general staff minute-by-minute control over rolling stock movements.', 'icon': 'gfx/interface/goals/GFX_TUR_civil_communitcations_improvements-96233.dds'}, 'TUR_zonguldak_coal_basin_drives': {'pt_t': 'Bacia Carbonífera de Zonguldak', 'en_t': 'Zonguldak Coal Mining Drive', 'pt_d': 'Investimentos estatais em poços de ventilação e guinchos a vapor dobram a extração de carvão mineral de alta qualidade para alimentar navios e ferrovias.', 'en_d': 'Heavy steam hoists and ventilation shafts double anthracite extraction along the Black Sea coast, fueling naval boilers and railway fireboxes.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_ergani_copper_mines': {'pt_t': 'Minas de Cobre de Ergani', 'en_t': 'Ergani Copper Mining Works', 'pt_d': 'A extração de minério de cobre nas montanhas de Diyarbakır garante suprimento doméstico essencial para a fabricação de estojos de munição e fios elétricos.', 'en_d': 'Rich copper lodes in the mountains near Diyarbakır provide the imperial arsenals with essential raw material for cartridge casings and telegraph wires.', 'icon': 'gfx/interface/goals/GFX_TUR_imperial_arsenal-96314.dds'}, 'TUR_tophane_ordnance_foundry': {'pt_t': 'Fundição Imperial de Tophane', 'en_t': 'Tophane Imperial Ordnance Foundry', 'pt_d': 'A histórica fundição de canhões no Bósforo é reformada com maquinário alemão, passando a refinar ligas de bronze e aço para peças de artilharia.', 'en_d': 'The historic ordnance works along the Bosphorus receive modern tempering forges, manufacturing quick-fire field artillery barrels and siege mounts.', 'icon': 'gfx/interface/goals/GFX_TUR_imperial_arsenal-96314.dds'}, 'TUR_bakirkoy_textile_mills': {'pt_t': 'Moinhos Têxteis de Bakırköy', 'en_t': 'Bakırköy State Textile Mills', 'pt_d': 'Teares a vapor produzem lã resistente e lonas impermeáveis para fardamento militar, casacos de inverno e barracas de campanha.', 'en_d': 'Steam looms turn domestic wool and cotton into durable uniform serge, greatcoats, and canvas field tents for the expanding armed forces.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_zeytinburnu_munitions_complex': {'pt_t': 'Complexo Fabril de Zeytinburnu', 'en_t': 'Zeytinburnu Munitions Complex', 'pt_d': 'Prensas mecânicas operam dia e noite na costa do Mar de Mármara, produzindo milhões de cartuchos Mauser e cápsulas de artilharia leve.', 'en_d': 'Precision presses along the Marmara coast operate day and night, turning out millions of Mauser rifle rounds and artillery propellant primers.', 'icon': 'gfx/interface/goals/GFX_TUR_arms_expansions-96239.dds'}, 'TUR_ankara_state_foundries': {'pt_t': 'Fundições Estatais de Ankara', 'en_t': 'Ankara State Metal Foundries', 'pt_d': 'Oficinas metalúrgicas instaladas no coração da Anatólia produzem ferramentas de sapa, ferraduras e granadas de mão protegidas de bombardeios costeiros.', 'en_d': 'Inland metallurgical workshops in Ankara cast entrenching tools, horseshoes, and trench grenades far beyond the range of enemy naval bombardment.', 'icon': 'gfx/interface/goals/GFX_TUR_ankara_industrialization-45108.dds'}, 'TUR_izmir_commercial_quays': {'pt_t': 'Ampliação dos Cais de Esmirna', 'en_t': 'Expansion of Smyrna Docks', 'pt_d': 'Novos guindastes a vapor e armazéns alfandegários no golfo de Esmirna facilitam o embarque rápido de tabaco, figos e trigo para o exterior.', 'en_d': 'Hydraulic cranes and deep-water berths in Smyrna harbor accelerate the export of raisins, figs, and Anatolian minerals to friendly ports.', 'icon': 'gfx/interface/goals/GFX_TUR_fleet_expansion-45124.dds'}, 'TUR_constantinople_electric_grid': {'pt_t': 'Eletrificação de Constantinopla', 'en_t': 'Constantinople Electrical Grid', 'pt_d': 'A usina termelétrica de Silahtarağa fornece energia abundante para bondes urbanos, arsenais do Chifre de Ouro e comunicações telegráficas.', 'en_d': 'The landmark Silahtarağa power plant energizes the imperial capital, supplying steady electric current to military workshops and communication nodes.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_amasya_metal_smelters': {'pt_t': 'Siderúrgicas de Amasya e Sivas', 'en_t': 'Amasya and Sivas Metal Works', 'pt_d': 'Forjas regionais processam minérios das montanhas pônticas, suprindo ferreiros e batalhões de engenharia com trilhos e vigas de ferro.', 'en_d': 'Inland foundries process ore from the Pontic mountains, fabricating structural iron beams and replacement rails for regional lines.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_imperial_munitions_directorate': {'pt_t': 'Diretoria Geral de Armamento', 'en_t': 'Imperial Munitions Directorate', 'pt_d': 'A centralização técnica sob o Ministério da Guerra elimina desperdício de pólvora e padroniza a produção fabril de projéteis e explosivos.', 'en_d': 'A centralized ordnance council streamlines powder production and oversees rigorous quality inspections across all state armories.', 'icon': 'gfx/interface/goals/GFX_TUR_office_of_war_industry-96076.dds'}, 'TUR_full_industrial_mobilization': {'pt_t': 'Mobilização Fabril de Guerra', 'en_t': 'Full Wartime Industrial Mobilization', 'pt_d': 'Todas as fundições privadas, oficinas ferroviárias e ateliês mecânicos são requisitados para a produção ininterrupta de material bélico.', 'en_d': 'Private smithies, locomotive repair sheds, and mechanical shops across the empire are mobilized under state contracts for urgent shell production.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_anatolian_grain_reserves': {'pt_t': 'Reservas de Grãos da Anatólia', 'en_t': 'Anatolian Strategic Grain Reserves', 'pt_d': 'Compras antecipadas de trigo e cevada enchem armazéns estatais em Konya e Ankara, protegendo as cidades imperiais contra inflação e fome.', 'en_d': 'Preemptive purchases of wheat and barley fill state granaries across the central plateau, shielding metropolitan centers from wartime famine.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_willcocks_mesopotamia_irrigation': {'pt_t': 'Projetos de Irrigação Willcocks', 'en_t': 'Willcocks Mesopotamia Irrigation Works', 'pt_d': 'A barragem de Hindiyya no Eufrates e novos canais restituem a lendária fertilidade dos campos mesopotâmicos para alimentar o exército.', 'en_d': 'The Hindiyya barrage across the Euphrates and restored silt canals revive Mesopotamian agricultural fertility, feeding the armies of the east.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdad_industrialization-45108.dds'}, 'TUR_cilicia_cotton_modernization': {'pt_t': 'Algodão Mecanizado da Cilícia', 'en_t': 'Cilician Cotton Modernization', 'pt_d': 'A planície de Çukurova recebe descaroçadeiras modernas e canais de drenagem, multiplicando a colheita do valioso algodão imperial.', 'en_d': 'The Çukurova plain receives modern hydraulic gins and drainage ditches, dramatically multiplying output of imperial long-staple cotton.', 'icon': 'gfx/interface/goals/GFX_TUR_law_for_encouraging_industry-86390.dds'}, 'TUR_anti_locust_campaigns': {'pt_t': 'Brigadas contra Pragas de Gafanhotos', 'en_t': 'Anti-Locust Campaign Brigadas', 'pt_d': 'Equipes de voluntários e soldados utilizam barreiras de zinco e lança-chamas para destruir nuvens de gafanhotos antes que devorem as colheitas do Levante.', 'en_d': 'Soldiers and agricultural leagues deploy zinc barriers and trench sprayers to eliminate locust swarms before they devastate Levant wheat fields.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_state_silos_and_famine_relief': {'pt_t': 'Silos de Ajuda Alimentar', 'en_t': 'State Silos and Famine Relief', 'pt_d': 'Redes de celeiros comunais em Beirute, Jerusalém e Aleppo distribuem farinha a preços subsidiados, impedindo tumultos populares.', 'en_d': 'Municipal grain reserves in Beirut, Aleppo, and Jerusalem distribute subsidized flour to families, maintaining social tranquility.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_ziraat_bankasi_credit_expansion': {'pt_t': 'Crédito Agrícola do Ziraat Bankası', 'en_t': 'Ziraat Bankası Agricultural Credit', 'pt_d': 'O Banco Agrícola Imperial concede empréstimos de baixo juro a pequenos proprietários para a aquisição de sementes selecionadas e arados de ferro.', 'en_d': 'The Imperial Agricultural Bank expands low-interest loans to peasant farmers, financing high-yield seeds and iron draft equipment.', 'icon': 'gfx/interface/goals/GFX_TUR_german_donation-96235.dds'}, 'TUR_mechanized_anatolian_farming': {'pt_t': 'Mecanização Agrícola da Anatólia', 'en_t': 'Mechanized Anatolian Farming', 'pt_d': 'Tratores a vapor e debulhadoras importadas operam nas grandes estepes férteis, compensando a falta de braços masculinos convocados às fileiras.', 'en_d': 'Steam tractors and mechanical threshers work the open Anatolian steppe, maintaining crop acreage despite the mobilization of farm hands.', 'icon': 'gfx/interface/goals/GFX_TUR_law_for_encouraging_industry-86390.dds'}, 'TUR_black_sea_timber_concessions': {'pt_t': 'Madeireiras do Mar Negro', 'en_t': 'Black Sea Timber Harvesting', 'pt_d': 'Serrarias florestais nas encostas do Ponto fornecem vigas de carvalho e pinho para escorar trincheiras e fabricar dormentes ferroviários.', 'en_d': 'Foresters in the lush Pontic mountains cut durable oak and pine timbers for trench duckboards, bunker pit-props, and railway sleepers.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_agrarian_surplus_storage': {'pt_t': 'Armazéns de Soberania Alimentar', 'en_t': 'Imperial Agrarian Surplus Depots', 'pt_d': 'Galpões secos e ventilados junto aos ramais ferroviários estocam excedentes de colheita protegidos da umidade e de ataques aéreos.', 'en_d': 'Well-ventilated storehouses alongside railway junctions safeguard millions of bushels of surplus grain against decay and hostile raids.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_breadbasket_of_the_empire': {'pt_t': 'O Celeiro Auto-Suficiente do Império', 'en_t': 'Breadbasket of the Empire', 'pt_d': 'A integração do planalto anatólio e dos vales férteis do Levante assegura que o Império Otomano não possa ser derrotado pela fome.', 'en_d': 'Coordinated cultivation across Anatolia and the Levant guarantees that the Ottoman Empire cannot be starved out by naval blockade.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}, 'TUR_integrated_imperial_economy': {'pt_t': 'Economia Imperial Integrada', 'en_t': 'Integrated Imperial Economy', 'pt_d': 'Carvão do Ponto, algodão da Cilícia, ferro de Ankara e trigo da Síria circulam sem entraves por um mercado nacional unificado e dinâmico.', 'en_d': 'Pontic coal, Cilician cotton, Anatolian iron, and Syrian flour circulate smoothly throughout a thriving, unified internal market.', 'icon': 'gfx/interface/goals/GFX_TUR_law_for_encouraging_industry-86390.dds'}, 'TUR_anatolian_highway_system': {'pt_t': 'Rodovias e Carroçáveis da Anatólia', 'en_t': 'Anatolian Road Network Expansion', 'pt_d': 'Estradas macadamizadas de rodagem conectam vilarejos rurais aos terminais ferroviários, facilitando o transporte de víveres e conscritos.', 'en_d': 'Crushed-stone arterial roads connect isolated rural valleys to trunk railheads, expediting the collection of farm produce and recruits.', 'icon': 'gfx/interface/goals/GFX_TUR_civil_communitcations_improvements-96233.dds'}, 'TUR_petroleum_concessions_mosul': {'pt_t': 'Pesquisa Petrolífera de Mosul', 'en_t': 'Mosul Petroleum Survey & Concessions', 'pt_d': 'Geólogos imperiais identificam os riquíssimos lençóis de óleo em Kirkuk e Qayyara, assegurando a reserva energética mais valiosa do futuro.', 'en_d': "Imperial geologists map the prolific oil seepages around Kirkuk and Mosul, securing sovereign control over the empire's vast petroleum future.", 'icon': 'gfx/interface/goals/GFX_TUR_baghdad_industrialization-45108.dds'}, 'TUR_sublime_porte_heavy_industry_board': {'pt_t': 'Conselho de Indústria Pesada', 'en_t': 'Sublime Porte Heavy Industry Board', 'pt_d': 'Engenheiros militares e industriais planejam a expansão de laminadores e fundições de aço capazes de produzir trilhos e chapas blindadas.', 'en_d': 'Industrialists and military engineers coordinate the expansion of steel mills capable of turning out heavy armor plate and artillery forgings.', 'icon': 'gfx/interface/goals/GFX_TUR_office_of_war_industry-96076.dds'}, 'TUR_autarkic_imperial_foundation': {'pt_t': 'Alicerce Autárquico do Império', 'en_t': 'Autarkic Imperial Foundations', 'pt_d': 'A nação conquista independência completa de insumos vitais, tornando o solo pátrio imune a chantagens de bloqueio marítimo ocidental.', 'en_d': 'The realm attains self-sufficiency in fundamental strategic materials, rendering imperial soil resilient against external embargoes.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_modern_ottoman_economic_miracle': {'pt_t': 'O Milagre Econômico da Sublime Porta', 'en_t': 'Modern Ottoman Economic Miracle', 'pt_d': 'A transição de um império endividado para um polo produtivo autônomo e respeitado demonstra o vigor inquebrantável do povo otomano.', 'en_d': 'The transformation from indebted debtor into an autonomous industrial power proves the inexhaustible vigor of the Ottoman realm.', 'icon': 'gfx/interface/goals/GFX_TUR_industrialization_of_the_nation-96238.dds'}, 'TUR_pontic_coal_shipping': {'pt_t': 'Frota Carbonífera do Mar Negro', 'en_t': 'Pontic Coal Shipping Flotilla', 'pt_d': 'Pequenos vapores e chalupas costeiras transportam o carvão de Zonguldak diretamente às forjas de Constantinopla sob escolta de torpedeiras.', 'en_d': 'Armored coastal colliers and sailing barges transport Black Sea coal under armed torpedo-boat escort directly to capital factories.', 'icon': 'gfx/interface/goals/GFX_TUR_fleet_expansion-45124.dds'}, 'TUR_cilicia_irrigation_canals': {'pt_t': 'Canais de Irrigação de Çukurova', 'en_t': 'Cilician Canal Infrastructure', 'pt_d': 'Sistemas de comportas no Rio Seyhan transformam a planície cilícia no maior polo produtor de fardamento e rações de todo o Mediterrâneo.', 'en_d': 'Hydraulic locks along the Seyhan River turn the Cilician plains into a premier production zone for imperial military rations and textile fibers.', 'icon': 'gfx/interface/goals/GFX_TUR_law_for_encouraging_industry-86390.dds'}, 'TUR_aleppo_commercial_hub': {'pt_t': 'Entreposto Comercial de Aleppo', 'en_t': 'Aleppo Continental Commercial Hub', 'pt_d': 'O histórico bazar de Aleppo floresce como o principal centro logístico de distribuição mercantil e militar entre a Síria e o Iraque.', 'en_d': 'The historic covered bazaars of Aleppo serve as the primary supply depot and rail junction linking Syria with Mesopotamian fronts.', 'icon': 'gfx/interface/goals/GFX_TUR_baghdadberlin_railway-86221.dds'}, 'TUR_syrian_grain_storage': {'pt_t': 'Armazéns Centrais de Cereais da Síria', 'en_t': 'Syrian Central Grain Silos', 'pt_d': 'Depósitos fortificados em Hama e Hauran acumulam trigo dourado para sustentar as guarnições das frentes meridionais e ocidentais.', 'en_d': 'Reinforced concrete grain elevators in Hama and the Hauran store durum wheat to sustain southern army corps throughout prolonged campaigns.', 'icon': 'gfx/interface/goals/GFX_TUR_1913_taxation_exemptions-50772.dds'}}
